{
  "states": [
    "REQUEST",
    "PARTOPEN",
    "RESPOND",
    "OPEN",
    "CLOSEREQ",
    "CLOSING",
    "TIMEWAIT"
  ],
  "transitions": [
    {
      "from": "REQUEST",
      "event": "P.type == Reset",
      "action": "Generate Reset(Packet Error) Drop packet",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "P.type == Sync or P.type == SyncAck",
      "action": "Update S.GSR, S.SWL, S.SWH",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "P.type == Sync or P.type == SyncAck",
      "action": "Drop packet",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "P.type == CloseReq or P.type == Close or P.type == Reset",
      "action": "Drop packet",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "P.type == Reset",
      "action": "Send Sync packet acknowledging S.GSR",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "P.type != Reset",
      "action": "Send Sync packet acknowledging P.seqno",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "P.type == CloseReq",
      "action": "Send Sync packet acknowledging P.seqno",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "P.type == Response",
      "action": "Send Sync packet acknowledging P.seqno",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "P.type == Request",
      "action": "Send Sync packet acknowledging P.seqno",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "P.type == Request and P.seqno >= S.OSR",
      "action": "Send Sync packet acknowledging P.seqno",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "P.type == Response and P.seqno >= S.OSR",
      "action": "Send Sync packet acknowledging P.seqno",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "P.type == Data",
      "action": "Send Sync packet acknowledging P.seqno",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "",
      "action": "Mark packet as acknowledgeable",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "P.type == Reset",
      "action": "Tear down connection S.state := TIMEWAIT Set TIMEWAIT timer Drop packet",
      "to": "TIMEWAIT"
    },
    {
      "from": "REQUEST",
      "event": "",
      "action": "S.state := PARTOPEN Set PARTOPEN timer",
      "to": "PARTOPEN"
    },
    {
      "from": "RESPOND",
      "event": "P.type == Request",
      "action": "Send Response, possibly containing Init Cookie",
      "to": "RESPOND"
    },
    {
      "from": "RESPOND",
      "event": "P.type == Request",
      "action": "Destroy S",
      "to": "RESPOND"
    },
    {
      "from": "RESPOND",
      "event": "P.type != Request",
      "action": "S.OSR := P.seqno S.state := OPEN",
      "to": "OPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "P.type == Response",
      "action": "Send Ack",
      "to": "PARTOPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "P.type != Sync",
      "action": "S.OSR := P.seqno S.state := OPEN",
      "to": "OPEN"
    },
    {
      "from": "OPEN",
      "event": "P.type == CloseReq and S.state < CLOSEREQ",
      "action": "Generate Close S.state := CLOSING Set CLOSING timer",
      "to": "CLOSING"
    },
    {
      "from": "CLOSING",
      "event": "P.type == Close",
      "action": "Generate Reset(Closed) Tear down connection Drop packet",
      "to": "CLOSING"
    },
    {
      "from": "OPEN",
      "event": "P.type == Sync",
      "action": "Generate SyncAck",
      "to": "OPEN"
    }
  ]
}

